mapper.select:
SELECT  FROM custom_field_definition
WHERE workspace_id = #{workspaceId}
ORDER BY entity_type, position, id

SELECT  FROM custom_field_definition
WHERE workspace_id = #{workspaceId} AND entity_type = #{entityType}
ORDER BY position, id

SELECT  FROM custom_field_definition
WHERE workspace_id = #{workspaceId} AND id = #{id}
FOR UPDATE

SELECT EXISTS(
  SELECT 1 FROM custom_field_definition WHERE workspace_id = #{workspaceId} AND id = #{id}
)

mapper.update:
UPDATE custom_field_definition
SET label = #{label}, field_type = #{fieldType}, data_classification = COALESCE(#{dataClassification}, 'standard'),
    options_json = #{optionsJson}, required = #{required}, position = #{position}, archived = #{archived}
WHERE workspace_id = #{workspaceId} AND id = #{id}
